"""Audited paired inference for the sealed fresh fine-tuning experiment."""
import argparse,hashlib,json
from collections import Counter
from pathlib import Path
import numpy as np
from qm_benchmark import STRATEGIES,hashfile
from finetune_core import messages,soft_targets,split_checks

def paired(stats,control,seed=20261118):
 lookup={(r['molecule'],r['policy']):r for r in stats};names=sorted({r['molecule'] for r in stats});groups={}
 for name in names:
  r=lookup[name,'finetuned_llm'];delta=r['normalized_auc']-lookup[name,control]['normalized_auc'];groups.setdefault(r['scaffold'],[]).append(delta)
 sums=np.array([sum(v) for v in groups.values()]);counts=np.array([len(v) for v in groups.values()]);rng=np.random.default_rng(seed)
 indices=rng.integers(len(groups),size=(10000,len(groups)));replicates=sums[indices].sum(axis=1)/counts[indices].sum(axis=1)
 delta=np.array([lookup[n,'finetuned_llm']['normalized_auc']-lookup[n,control]['normalized_auc'] for n in names])
 return {'control':control,'mean_paired_normalized_auc_difference':float(delta.mean()),'scaffold_cluster_95_percent_ci':np.quantile(replicates,[.025,.975]).tolist(),
  'wins':int((delta < -1e-12).sum()),'ties':int((abs(delta)<=1e-12).sum()),'losses':int((delta>1e-12).sum()),'scaffold_clusters':len(groups),'bootstrap_draws':10000}

def analyze(data,supervision,training,plans_dir,runs,out):
 data=Path(data);supervision=Path(supervision);training=Path(training);plans_dir=Path(plans_dir);runs=Path(runs);out=Path(out);out.mkdir(parents=True,exist_ok=True)
 assert (runs/'COMPLETE').exists() and (plans_dir/'COMPLETE').exists()
 split=json.loads((data/'split.json').read_text());inputs=json.loads((supervision/'inputs.json').read_text());teacher=json.loads((supervision/'teacher.json').read_text())
 datasets={n:json.loads((data/'datasets'/f'{n}.json').read_text()) for names in split['splits'].values() for n in names};groups=split_checks(datasets,split)
 for name in datasets:assert hashfile(data/'datasets'/f'{name}.json')==split['dataset_hashes'][name]
 assert set(teacher)==set(split['splits']['train']+split['splits']['validation']) and not set(teacher)&set(split['splits']['test'])
 for r in teacher.values():np.testing.assert_allclose([r['soft_targets'][s] for s in STRATEGIES],soft_targets([r['costs'][s] for s in STRATEGIES]))
 complete=json.loads((training/'training_complete.json').read_text());provenance=json.loads((training/'provenance.json').read_text());validation=json.loads((training/'validation.json').read_text());history=[json.loads(line) for line in (training/'training.jsonl').read_text().splitlines()]
 assert provenance['source_sha256']==hashfile(Path(__file__).with_name('finetune_mlx_stable.py'))
 assert provenance['protocol_sha256']==hashfile(Path(__file__).with_name('finetune_protocol_stable.json'))
 assert (training/'training_complete.json').stat().st_mtime <= (plans_dir/'manifest.json').stat().st_mtime <= (runs/'metrics.csv').stat().st_mtime
 assert complete['adapter_sha256']==hashfile(training/'adapters.safetensors') and complete['validation_file_sha256']==hashfile(training/'validation.json')
 assert complete['training_history_sha256']==hashfile(training/'training.jsonl') and provenance['split_sha256']==hashfile(data/'split.json')
 assert complete['selected_checkpoint']==min([v for v in validation if v['step']>0],key=lambda v:(v['mean_validation_normalized_auc'],v['step']))
 assert provenance['base_floating_dtype']=='bfloat16'
 assert len(history)==96 and all(r['rotations']==5 for r in history) and {r['training_molecule'] for r in history}==set(split['splits']['train'])
 assert all(n.rsplit('.',1)[-1] in ['lora_a','lora_b'] for n in provenance['trainable_names'])
 for v in validation:
  vp=json.loads((training/'validation'/f"step-{v['step']:03d}"/'plans.json').read_text())
  assert set(vp)==set(split['splits']['validation'])
  observed=np.mean([teacher[n]['costs'][p['strategy']] for n,p in vp.items()]);assert np.isclose(observed,v['mean_validation_normalized_auc'])
 plans=json.loads((plans_dir/'plans.json').read_text());manifest=json.loads((runs/'manifest.json').read_text());stats=json.loads((runs/'molecule_metrics.json').read_text())
 assert set(plans)==set(split['splits']['test']) and len(stats)==len(plans)*len(manifest['policies'])
 assert manifest['adapter_sha256']==complete['adapter_sha256'] and manifest['plans_sha256']==hashfile(plans_dir/'plans.json')
 extra=json.loads((runs/'extra_trees.json').read_text())['predictions']
 for name,pair in plans.items():
  expected_msgs,order=messages(inputs[name]);h=json.loads((runs/f'{name}-selections.json').read_text());pool={r['id'] for r in datasets[name]['pool']}
  for key in ['base','finetuned']:
   p=pair[key];request=json.loads((plans_dir/name/f'{key}-request.json').read_text());assert request['messages']==expected_msgs
   assert p['prompt_sha256']==hashlib.sha256(request['prompt'].encode()).hexdigest() and p['calls']==1
   assert p['input_sha256']==hashlib.sha256(json.dumps(inputs[name],sort_keys=True).encode()).hexdigest()
   assert p['strategy']==max(p['option_logits'],key=p['option_logits'].get) and np.isfinite(list(p['option_logits'].values())).all()
  assert pair['base']['prompt_sha256']==pair['finetuned']['prompt_sha256']
  for seed in range(5):
   for policy in manifest['policies']:
    ids=h[f'{policy}_{seed}'];assert len(ids)==len(set(ids))==12 and set(ids)<=pool and ids[:4]==h[f'bayes_{seed}'][:4]
   for policy,strategy in [('base_llm',pair['base']['strategy']),('finetuned_llm',pair['finetuned']['strategy']),('extra_trees',extra[name]['strategy'])]:
    fixed='bayes' if strategy=='uniform' else 'fixed_'+strategy;assert h[f'{policy}_{seed}']==h[f'{fixed}_{seed}']
 means={p:{k:float(np.mean([r[k] for r in stats if r['policy']==p])) for k in ['normalized_auc','auc','final_rmse','normalized_final_rmse']} for p in manifest['policies']}
 comparisons=[paired(stats,c,20261118+i) for i,c in enumerate(['bayes','rule','base_llm','extra_trees','training_global'])]
 fixed=['bayes']+['fixed_'+s for s in STRATEGIES if s!='uniform'];oracle=np.mean([min(r['normalized_auc'] for r in stats if r['molecule']==n and r['policy'] in fixed) for n in plans])
 audit={'valid_counts':split['valid_counts'],'scaffold_counts':split['scaffold_counts'],'fresh_test_overlap_with_any_previous_scaffold':0,'all_split_scaffold_overlaps':0,
  'previous_test_scaffold_molecules_quarantined':split['quarantined_previous_test_scaffold_molecules'],'trainable_parameters':provenance['trainable_parameters'],
  'adapter_selection_precedes_planning_and_label_scoring':True,'teacher_has_no_fresh_test_targets':True,'all_teacher_soft_targets_match_costs':True,'all_model_inputs_and_budgets_match':True,'all_model_and_tree_actions_match_fixed_controls':True,
  'selected_checkpoint':complete['selected_checkpoint'],'trained_updates':96,'gradient_microsteps':480,'training_wall_seconds':complete['wall_seconds'],
  'fresh_model_decisions':len(plans)*2,'trajectories':len(plans)*len(manifest['policies'])*5,'primary_beats_bayes':comparisons[0]['scaffold_cluster_95_percent_ci'][1]<0,
  'comparisons':comparisons,'means':means,'retrospective_menu_oracle_normalized_auc':float(oracle),
  'strategies':{k:dict(Counter(p[k]['strategy'] for p in plans.values())) for k in ['base','finetuned']},
  'letters':{k:dict(Counter(p[k]['chosen_letter'] for p in plans.values())) for k in ['base','finetuned']},
  'planning':{k:{'seconds':sum(p[k]['seconds'] for p in plans.values()),'median_seconds':float(np.median([p[k]['seconds'] for p in plans.values()])),
   'prompt_tokens':sum(p[k]['prompt_tokens'] for p in plans.values())} for k in ['base','finetuned']}}
 if (out/'independent-data-audit.json').exists():audit['independent_data']=json.loads((out/'independent-data-audit.json').read_text())
 (out/'analysis.json').write_text(json.dumps(audit,indent=2));test_n=len(plans)
 lines=['# QM-supervised BF16 QLoRA acquisition: fresh test','', '**Primary result: '+('the fine-tuned planner beats pure Bayes under the prespecified criterion.' if audit['primary_beats_bayes'] else 'no reliable improvement over pure Bayes was demonstrated.')+'** The primary comparison is the fine-tuned model minus Bayes in molecule-mean normalized error-query AUC, with a paired 95% scaffold-cluster bootstrap interval. Lower is better.','', '## Frozen design and fresh data','', f"Training: {split['valid_counts']['train']} molecular parents / {len(groups['train'])} scaffold groups. Validation: {split['valid_counts']['validation']} parents / {len(groups['validation'])} groups. Fresh test: {test_n} parents / {len(groups['test'])} groups. No train/validation/test scaffold overlap. Fresh validation and test also exclude every scaffold from the previous experiment, and all {split['quarantined_previous_test_scaffold_molecules']} eligible molecules in the previous test scaffold groups are quarantined entirely. All selected QM records were independently verified complete at Psi4 B3LYP-D3BJ/DZVP before teacher generation; no QC exclusions were needed.", '', 'The same complete 24-point 1D torsion scans, 16-point acquisition pools, 8-point within-molecule evaluation sets, Fourier harmonics 1–3, UFF baseline, Gaussian prior and fixed noise as the previous experiment are used. Five matched seeds, four initial labels, batches of two, twelve labels total. No new quantum calculations were commissioned.','', '## Numerical repair before test scoring','', 'The original FP16 attempt failed a nonfinite check at update 84. Its saved checkpoints and partial unlabeled fresh predictions were preserved as diagnostic artifacts. No fresh QM acquisition outcomes had been scored. The repaired trial used BF16 compute, checks on every loss/gradient before optimizer updates, and saved optimizer checkpoints. Splits, QM supervision, hyperparameters, model architecture, checkpoint selection and the primary comparison were unchanged. The complete 96-update schedule was then run from initialization; this report evaluates that stable retry, not the interrupted model.','', '## What was fine-tuned','', f"Qwen2.5-7B-Instruct, using the same pinned 4-bit base weights. Only {provenance['trainable_parameters']:,} LoRA parameters on query/value attention projections in the last two decoder blocks are updated (rank 8, scale 8, dropout 0). Floating base tensors are cast to BF16 before freezing; quantized integer weight tensors are unchanged. Adapter tensors are FP32. The matched untuned baseline uses the same BF16 representation. The optimizer is AdamW with learning rate 2e-4, weight decay 0.01, norm clipping 1.0, seed 20261118.", '', 'The supervision is a QM-derived acquisition preference, not raw energy text. For each training and validation molecule only, all five existing strategies are replayed over five seeds. Their mean normalized AUC values define a soft action target proportional to exp(-cost/0.05). Training minimizes soft cross entropy over five action-letter logits. Each update averages all five cyclic option permutations for one molecule, exactly balancing strategy-to-letter placement. There are 96 updates / 480 gradient microsteps.','', 'The compact prompt contains the molecular graph with driven atoms mapped, bond-specific descriptors and unlabeled pool angles, plus the five score formulas. There are no energies, teacher costs, source record IDs or few-shot examples in the prompt. The matched untuned base model uses exactly the same prompt and decoding. This is supervised cost-sensitive QLoRA, not reinforcement learning and not direct force-field parameter generation.','', f"Checkpoints at updates 24, 48, 72 and 96 were compared on validation acquisition AUC. Update {complete['selected_checkpoint']['step']} was selected at validation AUC {complete['selected_checkpoint']['mean_validation_normalized_auc']:.6f}; base validation AUC was {validation[0]['mean_validation_normalized_auc']:.6f}. The selection rule and hyperparameters were frozen before training. Only after checkpoint selection were the two fresh model decisions generated, followed by fresh QM outcome scoring. No retraining followed fresh test inspection.", '', '## Fresh test performance','', 'AUC is the trapezoidal mean centered test residual RMSE across 4–12 queries, normalized by each molecule’s centered QM-minus-UFF baseline RMSE, then averaged over seeds and molecules. The normalizer is used only by the evaluator.','', '| Policy | Normalized AUC | AUC (kcal/mol) | Final RMSE (kcal/mol) |','|---|---:|---:|---:|']
 for p,r in means.items():lines.append(f"| {p} | {r['normalized_auc']:.6f} | {r['auc']:.6f} | {r['final_rmse']:.6f} |")
 lines+=['','## Paired comparisons','', 'Negative differences favor the fine-tuned LLM. Seeds are averaged before resampling whole scaffold clusters. Only the comparison against Bayes is the prespecified primary 95% interval; other intervals are descriptive secondary comparisons.','', '| Comparator | Fine-tuned minus control normalized AUC | 95% cluster interval | Wins / ties / losses |','|---|---:|---|---|']
 for c in comparisons:
  lo,hi=c['scaffold_cluster_95_percent_ci'];lines.append(f"| {c['control']} | {c['mean_paired_normalized_auc_difference']:+.6f} | [{lo:+.6f}, {hi:+.6f}] | {c['wins']} / {c['ties']} / {c['losses']} |")
 lines+=['', 'The learned non-LLM control is an ExtraTrees multioutput regressor predicting each strategy’s regret relative to Bayes. It is trained on the same training molecules and QM supervision, using 256-bit Morgan radius-2 features and chemical/angular coverage descriptors. Its parameters are frozen (256 trees, min leaf 3, max features 0.5); validation/test labels are not used to fit it. All fixed strategies, the training-global best strategy and random acquisition are also included.', '',f"A retrospective per-molecule best-in-menu oracle reaches normalized AUC {oracle:.6f}. This oracle uses fresh outcomes after evaluation and is not a deployable baseline or a trained model; it only describes the finite strategy menu’s headroom.", '', '## Training, behavior and latency','',f"Measured training plus validation took {complete['wall_seconds']/60:.2f} minutes, excluding model loading and preparation. The selected adapter SHA256 is `{complete['adapter_sha256']}`. Full training loss, gradient norms, checkpoint decisions and scores are retained.", '']
 for k in ['base','finetuned']:
  lines.append(f"{k}: strategy counts `{json.dumps(audit['strategies'][k],sort_keys=True)}`; letter counts `{json.dumps(audit['letters'][k],sort_keys=True)}`. {len(plans)} decisions took {audit['planning'][k]['seconds']:.1f} seconds; median {audit['planning'][k]['median_seconds']:.3f} seconds per molecule.")
 lines+=['', 'Option frequencies diagnose behavior but do not establish counterfactual order invariance. Balanced training covers all five positions per molecule; each fresh model is called once per molecule, not five times. Inference and training ran locally on the Apple M2 GPU, with no new AWS resources or paid model API.','', '## Audit and interpretation limits','', 'All dataset, adapter and prompt hashes are checked. Teacher targets contain only training/validation molecules. Training history uses only training parents. Validation scores are independently reconstructed from validation teacher costs. Fresh prompts are checked against the label-free allowlist; base and tuned prompts are identical. Every policy has the same initial set, twelve unique pool-only acquisitions, and no evaluation geometry IDs. Both LLMs and the learned selector exactly reproduce their corresponding fixed-strategy controls.', '', 'This is a small fine-tuning pilot with only 95 training parents and 37 training scaffold groups, and a single fine-tuning seed. Intervals quantify scaffold/molecule variation conditional on this selected adapter, not variability across training seeds. Fresh scaffold separation does not guarantee low fingerprint similarity, and public molecules may have appeared in LLM pretraining. The complete-scan selection biases coverage. Tests interpolate within a constrained scan; they do not validate new conformer families. The geometry pool itself was QM-optimized, so replay does not establish prospective QM time savings. The correction fit remains a fixed linear Gaussian model: acquisition within the chosen plan uses geometry and covariance rather than observed energies. No MD accuracy, force-field export improvement or general-purpose force-field learning is established. Do not tune on this fresh set and call another run independent.', '', '## Sources and reproduction','', '- [Pinned public OpenFF Sage 2.2.1 QM fitting data](https://github.com/openforcefield/sage-2.2.1).','- [MLX-LM LoRA/QLoRA implementation](https://github.com/ml-explore/mlx-lm/blob/main/mlx_lm/LORA.md).','- [Qwen2.5-7B-Instruct quantized model](https://huggingface.co/mlx-community/Qwen2.5-7B-Instruct-4bit).','', 'The companion archive contains frozen protocol and splits, source-member hashes, selected QM/UFF data, teacher values, all model prompts and decisions, every adapter checkpoint, validation selection records, baseline predictions, per-seed metrics and candidate IDs, and source code. Base model weights are referenced by hash and are not redistributed.','']
 if 'independent_data' in audit:
  d=audit['independent_data'];sim=d['fresh_test_to_training_Morgan_radius2_2048_Tanimoto'];lines += [f"Independent source verification checked {d['qm_frames_checked']} QM frames and all source-file hashes. Nearest-training Morgan radius-2/2048-bit Tanimoto similarity on fresh test molecules has median {sim['median']:.3f}, 95th percentile {sim['p95']:.3f} and maximum {sim['maximum']:.3f}.",'']
 (out/'REPORT.md').write_text('\n'.join(lines));print(json.dumps({k:v for k,v in audit.items() if k not in ['means']},indent=2))

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--data',required=True);p.add_argument('--supervision',required=True);p.add_argument('--training',required=True);p.add_argument('--plans-dir',required=True);p.add_argument('--runs',required=True);p.add_argument('--out',required=True);a=p.parse_args();analyze(a.data,a.supervision,a.training,a.plans_dir,a.runs,a.out)
